13	// ============================================================
14	// 索引类算子 op_host 参考代码（单行更新 / index_select 风格）
15	// 适用: index_select, index_add 等 1D 共享索引算子
16	// 示例: 以 torch.index_select(input, dim, index) 为例
17	//       index 为 1D，所有行共享，无需 transpose
18	//       3D 布局: [outerSize, srcDimSize, innerSize]
19	//       动态核分配: coresPerOuter 按索引批次自适应
20	// ============================================================
21	
22	#include "torch_kernel_helper.h"
23	#include "aclrtlaunch_<op_name>.h"
24	#include <torch/extension.h>
25	
26	namespace ascend_kernel {
27	
28	constexpr int64_t MAX_CORES = 40;
29	constexpr int64_t MAX_INDEX_BATCH = 512;  // indexBuf 每核最大容量
30	
31	at::Tensor <op_name>(const at::Tensor& input, int64_t dim, const at::Tensor& index) {
32	    // ---- 输入校验 ----
33	    TORCH_CHECK(input.device().type() == at::DeviceType::PrivateUse1,
34	                "<op_name>: input must be on NPU device");
35	    TORCH_CHECK(index.device().type() == at::DeviceType::PrivateUse1,
36	                "<op_name>: index must be on NPU device");
37	
38	    int64_t ndim = input.dim();
39	    if (dim < 0) dim += ndim;
40	
41	    TORCH_CHECK(dim >= 0 && dim < ndim,
42	                "<op_name>: dim out of range, got dim=", dim);
43	    TORCH_CHECK(index.dim() == 1,
44	                "<op_name>: index must be 1D");
45	
46	    TORCH_CHECK(input.scalar_type() == at::kFloat ||
47	                input.scalar_type() == at::kHalf ||
48	                input.scalar_type() == at::kBFloat16,
49	                "<op_name>: only float32, float16 and bfloat16 are supported");
50	
51	    // ---- 连续化 ----
52	    at::Tensor inputContiguous = input.contiguous();
53	    at::Tensor indexContiguous = index.contiguous();
54	
55	    // ---- 3D 维度参数 ----
56	    // 无需 transpose，直接按 3D 布局计算偏移:
57	    //   input:  [outerSize, srcDimSize, innerSize]
58	    //   output: [outerSize, indexSize,  innerSize]
59	    int64_t outerSize = 1;
60	    for (int64_t i = 0; i < dim; i++) outerSize *= inputContiguous.size(i);
61	
62	    int64_t srcDimSize = inputContiguous.size(dim);
63	
64	    int64_t innerSize = 1;
65	    for (int64_t i = dim + 1; i < ndim; i++) innerSize *= inputContiguous.size(i);
66	
67	    int64_t indexSize = indexContiguous.size(0);
68	    int64_t totalLength = outerSize * indexSize * innerSize;
69	
70	    // 搬运类算子不做数值计算，bf16 可直接按 fp16 路径搬运
71	    int64_t dtypeSize = inputContiguous.element_size();
72	
73	    // ---- Index 转 int32 ----
74	    auto indexInt32 = indexContiguous.to(at::kInt);
75	    // Host 端发送元素索引，Kernel 端直接按 3D 偏移访问
76	
77	    // ---- 输出张量 ----
78	    // 输出形状: input.shape[:dim] + [indexSize] + input.shape[dim+1:]
79	    auto outputShape = inputContiguous.sizes().vec();
80	    outputShape[dim] = indexSize;
81	    auto output = at::empty(outputShape, inputContiguous.options());
82	
83	    if (totalLength == 0) return output;
84	
85	    // ---- Block 级 Tiling: 动态核分配 ----
86	    // 每个 outer 按 index 批次分配核数，最大化 indexBuf 利用率
87	    int64_t indexBatchSize = std::max(int64_t(1), std::min(indexSize, MAX_INDEX_BATCH));
88	    TORCH_CHECK(indexBatchSize != 0, "indexBatchSize should not be 0");
89	    int64_t idealCoresPerOuter = (indexSize + indexBatchSize - 1) / indexBatchSize;
90	    if (idealCoresPerOuter < 1) idealCoresPerOuter = 1;
91	
92	    int64_t totalTasks = outerSize * idealCoresPerOuter;
93	    int64_t coresPerOuter;
94	    uint32_t blockDim;
95	
96	    if (totalTasks <= MAX_CORES) {
97	        coresPerOuter = idealCoresPerOuter;
98	        blockDim = static_cast<uint32_t>(totalTasks);
99	    } else {
100	        coresPerOuter = MAX_CORES / outerSize;
101	        if (coresPerOuter < 1) coresPerOuter = 1;
102	        blockDim = MAX_CORES;
103	    }
104	    if (blockDim < 1) blockDim = 1;
105	
106	    EXEC_KERNEL_CMD(<op_name>, blockDim, inputContiguous, indexInt32, output,
107	                    outerSize, innerSize, indexSize, srcDimSize,
108	                    totalLength, coresPerOuter);
109	
110	    return output;
111	}
112	
113	}  // namespace ascend_kernel
