5	namespace ascend_kernel {
6	
7	constexpr int64_t MAX_CORES = 40;
8	constexpr int64_t CACHE_LINE_BYTES = 512;
9	
10	at::Tensor quant_scatter(
11	    const at::Tensor &input,
12	    const at::Tensor &indices,
13	    const at::Tensor &updates,
14	    const at::Tensor &quant_scales,
15	    const c10::optional<at::Tensor> &quant_zero_points,
16	    int64_t axis,
17	    int64_t quant_axis,
18	    std::string reduce)
19	{
20	    // ---- Input validation ----
21	    TORCH_CHECK(input.device().type() == at::DeviceType::PrivateUse1,
22	                "quant_scatter: input must be on NPU device");
23	    TORCH_CHECK(indices.device().type() == at::DeviceType::PrivateUse1,
24	                "quant_scatter: indices must be on NPU device");
25	    TORCH_CHECK(updates.device().type() == at::DeviceType::PrivateUse1,
26	                "quant_scatter: updates must be on NPU device");
27	
28	    TORCH_CHECK(input.scalar_type() == at::kChar || input.scalar_type() == at::kByte,
29	                "quant_scatter: input must be int8");
30	    TORCH_CHECK(indices.scalar_type() == at::kInt,
31	                "quant_scatter: indices must be int32");
32	    TORCH_CHECK(updates.scalar_type() == at::kHalf || updates.scalar_type() == at::kBFloat16,
33	                "quant_scatter: updates must be float16 or bfloat16");
34	
35	    bool hasZeroPoint = quant_zero_points.has_value();
36	
37	    // ---- Handle axis ----
38	    int64_t ndim = input.dim();
39	    if (axis < 0) axis += ndim;
40	    if (quant_axis < 0) quant_axis += ndim;
41	
42	    // ---- Continuity ----
43	    at::Tensor inputContiguous = input.contiguous();
44	    at::Tensor indicesContiguous = indices.contiguous();
45	    at::Tensor updatesContiguous = updates.contiguous();
46	    // Cast updates, scales, zp to float32 for kernel simplicity
47	    updatesContiguous = updatesContiguous.to(at::kFloat).contiguous();
48	    at::Tensor scalesContiguous = quant_scales.contiguous();
49	    scalesContiguous = scalesContiguous.to(at::kFloat).contiguous();
50	    at::Tensor zpContiguous;
51	    if (hasZeroPoint) {
52	        auto zpRaw = quant_zero_points.value().contiguous();
53	        // Always cast zp to float32 for kernel (handles both int32 and bf16)
54	        zpContiguous = zpRaw.to(at::kFloat).contiguous();
55	    }
56	
57	    // ---- Extract dimensions ----
58	    int64_t batchSize = indicesContiguous.size(0);  // N
59	    int64_t innerSize = inputContiguous.size(axis);  // M
60	    int64_t channelSize = inputContiguous.size(quant_axis);  // K
61	    int64_t totalElements = inputContiguous.numel();
62	
63	    // ---- Create output (clone input) ----
64	    auto output = inputContiguous.clone();
65	
66	    // ---- Get platform info ----
67	    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
68	    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
69	    uint64_t ubSize;
70	    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
71	
72	    int64_t usedCoreNum = (batchSize < coreNum) ? batchSize : coreNum;
73	    if (usedCoreNum < 1) usedCoreNum = 1;
74	
75	    // ---- UB Tiling: Single TQue approach ----
76	    // inQueue BUFFER_NUM=4 + outQueue BUFFER_NUM=1 = 5 * tileLength bytes
77	    // Scatter phase reuses inQueue slots (each slot needs ≥ tileChannel * 4 bytes)
78	    // So tileLength = tileChannel * 4 (one float per element per slot)
79	    // UB = 5 * tileLength ≤ ubSize → tileLength ≤ ubSize / 5
80	    int64_t totalBufferCoeff = 5;  // 4 inQueue + 1 outQueue
81	    int64_t maxTileElements = static_cast<int64_t>(ubSize) / totalBufferCoeff;
82	    int64_t alignCopyElems = 32;   // 32B alignment for int8
83	    int64_t tileLength = (maxTileElements / alignCopyElems) * alignCopyElems;
84	    if (tileLength < alignCopyElems) tileLength = alignCopyElems;
85	
86	    // Scatter tile = tileLength / 4 (each element needs float = 4 bytes per slot)
87	    int64_t alignChannelElems = 8;  // 32B alignment for float
88	    int64_t tileChannel = tileLength / 4;
89	    tileChannel = (tileChannel / alignChannelElems) * alignChannelElems;
90	    if (tileChannel < alignChannelElems) tileChannel = alignChannelElems;
91	    // Re-derive tileLength to satisfy tileLength = tileChannel * 4 (for float slot alignment)
92	    tileLength = tileChannel * 4;
93	
94	    // ---- Dtype flags (simplified: scales and zp always float32 on host) ----
95	    int64_t updatesDtype = (updatesContiguous.scalar_type() == at::kBFloat16) ? 1 : 0;
96	    int64_t scalesDtype = 0;   // always float32
97	    int64_t zeroPointFlag = hasZeroPoint ? 1 : 0;
98	    int64_t zpDtype = 0;       // always float32
99	    int64_t reduceMode = 0;    // placeholder
100	
101	    // ---- Tiling data struct ----
102	    struct TilingData {
103	        int64_t batchSize;
104	        int64_t innerSize;
105	        int64_t channelSize;
106	        int64_t totalElements;
107	        int64_t usedCoreNum;
108	        int64_t tileLength;
109	        int64_t tileChannel;
110	        int64_t updatesDtype;
111	        int64_t scalesDtype;
112	        int64_t zeroPointFlag;
113	        int64_t zpDtype;
114	        int64_t reduceMode;
115	    };
116	
117	    TilingData tilingData = {
118	        batchSize, innerSize, channelSize, totalElements,
119	        usedCoreNum, tileLength, tileChannel,
120	        updatesDtype, scalesDtype, zeroPointFlag, zpDtype, reduceMode
121	    };
122	
123	    // Copy tiling data to NPU
124	    auto tilingTensorCpu = at::empty({static_cast<int64_t>(sizeof(TilingData))},
125	                                     at::TensorOptions().dtype(at::kByte));
126	    auto tilingPtr = tilingTensorCpu.data_ptr<uint8_t>();
127	    std::memcpy(tilingPtr, &tilingData, sizeof(TilingData));
128	    auto tilingTensor = tilingTensorCpu.to(input.device());
129	
130	    // ---- All params must be left-values ----
131	    int64_t blockDimVal = usedCoreNum;
132	
133	    if (hasZeroPoint) {
134	        EXEC_KERNEL_CMD(quant_scatter, blockDimVal,
135	                        inputContiguous, indicesContiguous, updatesContiguous,
136	                        scalesContiguous, zpContiguous, output, tilingTensor);
137	    } else {
138	        auto dummyZp = at::empty({1}, at::TensorOptions().dtype(at::kInt).device(input.device()));
139	        EXEC_KERNEL_CMD(quant_scatter, blockDimVal,
140	                        inputContiguous, indicesContiguous, updatesContiguous,
141	                        scalesContiguous, dummyZp, output, tilingTensor);
142	    }
143	
144	    return output;
145	}
