3	using namespace AscendC;
4	
5	constexpr int64_t IN_BUF_NUM = 4;
6	constexpr int64_t OUT_BUF_NUM = 1;
7	
8	class KernelQuantScatter {
9	public:
10	    __aicore__ inline KernelQuantScatter() {}
11	
12	    __aicore__ inline void Init(
13	        GM_ADDR input, GM_ADDR indices, GM_ADDR updates,
14	        GM_ADDR scales, GM_ADDR zp, GM_ADDR output,
15	        int64_t batchSize, int64_t innerSize, int64_t channelSize,
16	        int64_t totalElements, int64_t usedCoreNum,
17	        int64_t tileLength, int64_t tileChannel,
18	        int64_t zeroPointFlag) {
19	        batchSize_ = batchSize;
20	        innerSize_ = innerSize;
21	        channelSize_ = channelSize;
22	        totalElements_ = totalElements;
23	        usedCoreNum_ = usedCoreNum;
24	        tileLength_ = tileLength;
25	        tileChannel_ = tileChannel;
26	        zeroPointFlag_ = zeroPointFlag;
27	
28	        inputGm_.SetGlobalBuffer((__gm__ int8_t*)input, totalElements_);
29	        indicesGm_.SetGlobalBuffer((__gm__ int32_t*)indices, batchSize_);
30	        outputGm_.SetGlobalBuffer((__gm__ int8_t*)output, totalElements_);
31	
32	        updatesGm_.SetGlobalBuffer((__gm__ float*)updates, batchSize_ * channelSize_);
33	        scalesGm_.SetGlobalBuffer((__gm__ float*)scales, channelSize_);
34	        if (zeroPointFlag_) {
35	            zpGm_.SetGlobalBuffer((__gm__ float*)zp, channelSize_);
36	        }
37	
38	        // inQueue: shared between copy (int8) and scatter (float/half) phases
39	        // outQueue: shared between copy (int8) and scatter (int8) phases
40	        int64_t inSlotBytes = tileLength_;
41	        int64_t outSlotBytes = tileLength_;
42	        pipe_.InitBuffer(inQueue_, IN_BUF_NUM, inSlotBytes);
43	        pipe_.InitBuffer(outQueue_, OUT_BUF_NUM, outSlotBytes);
44	    }
45	
46	    __aicore__ inline void Process() {
47	        int64_t blockIdx = GetBlockIdx();
48	        if (blockIdx >= usedCoreNum_) return;
49	
50	        for (int64_t n = blockIdx; n < batchSize_; n += usedCoreNum_) {
51	            ProcessRow(n);
52	        }
53	    }
54	
55	private:
56	    __aicore__ inline void ProcessRow(int64_t n) {
57	        int64_t rowTotal = innerSize_ * channelSize_;
58	        int64_t rowBase = n * rowTotal;
59	        int64_t tileNum = (rowTotal + tileLength_ - 1) / tileLength_;
60	
61	        // Phase 1: Copy input→output
62	        for (int64_t t = 0; t < tileNum; t++) {
63	            int64_t curLen = (t == tileNum - 1) ? (rowTotal - t * tileLength_) : tileLength_;
64	            CopyChunk(rowBase + t * tileLength_, curLen);
65	        }
66	
67	        // Phase 2: Scatter-quantize
68	        int64_t idx = indicesGm_.GetValue(n);
69	        if (idx < 0 || idx >= innerSize_) return;
70	
71	        for (int64_t k = 0; k < channelSize_; k += tileChannel_) {
72	            int64_t curK = (k + tileChannel_ > channelSize_) ? (channelSize_ - k) : tileChannel_;
73	            ScatterQuantizeChunk(n, idx, k, curK);
74	        }
75	    }
76	
77	    __aicore__ inline void CopyChunk(int64_t offset, int64_t length) {
78	        // Read GM→UB with DataCopyPad
79	        LocalTensor<int8_t> src = inQueue_.AllocTensor<int8_t>();
80	        DataCopyExtParams p;
81	        p.blockCount = 1;
82	        p.blockLen = static_cast<uint32_t>(length * sizeof(int8_t));
83	        p.srcStride = 0; p.dstStride = 0;
84	        DataCopyPadExtParams<int8_t> pad;
85	        pad.isPad = false;
86	        DataCopyPad(src, inputGm_[offset], p, pad);
87	        // Ensure DMA completes before DeQue
88	        PipeBarrier<PIPE_ALL>();
89	        inQueue_.EnQue(src);
90	
91	        // Dequeue and write UB→GM
92	        LocalTensor<int8_t> data = inQueue_.DeQue<int8_t>();
93	        DataCopyExtParams op;
94	        op.blockCount = 1;
95	        op.blockLen = static_cast<uint32_t>(length * sizeof(int8_t));
96	        op.srcStride = 0; op.dstStride = 0;
97	        DataCopyPad(outputGm_[offset], data, op);
98	        PipeBarrier<PIPE_ALL>();
99	        inQueue_.FreeTensor(data);
100	    }
101	
102	    __aicore__ inline void ScatterQuantizeChunk(int64_t n, int64_t idx, int64_t kStart, int64_t tileK) {
103	        // Use inQueue (4 slots) for simultaneous scatter buffers:
104	        // Slot 0: scales float
105	        // Slot 1: zp float
106	        // Slot 2: updates (updatesT)
107	        // Slot 3: compute float / temp int16
108	
109	        // --- Slot 0: Load scales ---
110	        LocalTensor<float> scalesFp32 = inQueue_.AllocTensor<float>();
111	        {
112	            DataCopyExtParams p;
113	            p.blockCount = 1;
114	            p.blockLen = static_cast<uint32_t>(tileK * sizeof(float));
115	            p.srcStride = 0; p.dstStride = 0;
116	            DataCopyPadExtParams<float> pad; pad.isPad = false;
117	            DataCopyPad(scalesFp32, scalesGm_[kStart], p, pad);
118	        }
119	        inQueue_.EnQue(scalesFp32);
120	        scalesFp32 = inQueue_.DeQue<float>();
121	        PipeBarrier<PIPE_ALL>();
122	
123	        // --- Slot 1: Load zp or zero ---
124	        LocalTensor<float> zpFp32 = inQueue_.AllocTensor<float>();
125	        if (zeroPointFlag_) {
126	            DataCopyExtParams p;
127	            p.blockCount = 1;
128	            p.blockLen = static_cast<uint32_t>(tileK * sizeof(float));
129	            p.srcStride = 0; p.dstStride = 0;
130	            DataCopyPadExtParams<float> pad; pad.isPad = false;
131	            DataCopyPad(zpFp32, zpGm_[kStart], p, pad);
132	        } else {
133	            Duplicate(zpFp32, 0.0f, tileK);
134	        }
135	        inQueue_.EnQue(zpFp32);
136	        zpFp32 = inQueue_.DeQue<float>();
137	        PipeBarrier<PIPE_ALL>();
138	
139	        // --- Slot 2: Load updates (float32) ---
140	        LocalTensor<float> updatesSrc = inQueue_.AllocTensor<float>();
141	        {
142	            DataCopyExtParams p;
143	            p.blockCount = 1;
144	            p.blockLen = static_cast<uint32_t>(tileK * sizeof(float));
145	            p.srcStride = 0; p.dstStride = 0;
146	            DataCopyPadExtParams<float> pad; pad.isPad = false;
147	            int64_t gmOff = n * channelSize_ + kStart;
148	            DataCopyPad(updatesSrc, updatesGm_[gmOff], p, pad);
149	        }
150	        inQueue_.EnQue(updatesSrc);
151	        updatesSrc = inQueue_.DeQue<float>();
152	        PipeBarrier<PIPE_ALL>();
153	
154	        // --- Slot 3: Compute (updates already FP32) ---
155	        LocalTensor<float> computeFp32 = inQueue_.AllocTensor<float>();
156	        // computeFp32 = updatesSrc / scalesFp32
157	        Div(computeFp32, updatesSrc, scalesFp32, tileK);
158	        inQueue_.FreeTensor(updatesSrc); // free slot 2
159	        PipeBarrier<PIPE_ALL>();
160	        PipeBarrier<PIPE_ALL>();
161	
162	        Add(computeFp32, computeFp32, zpFp32, tileK);
163	        inQueue_.FreeTensor(scalesFp32); // free slot 0
164	        inQueue_.FreeTensor(zpFp32);     // free slot 1
165	        PipeBarrier<PIPE_ALL>();
166	
167	        // Clamp
168	        Mins(computeFp32, computeFp32, 127.0f, tileK);
169	        PipeBarrier<PIPE_ALL>();
170	        Maxs(computeFp32, computeFp32, -128.0f, tileK);
171	        PipeBarrier<PIPE_ALL>();
172	
173	        // FP32 → int16 (rounding, AscendC supported)
174	        LocalTensor<int16_t> tempInt16 = inQueue_.AllocTensor<int16_t>();
175	        Cast(tempInt16, computeFp32, RoundMode::CAST_ROUND, tileK);
176	        inQueue_.FreeTensor(computeFp32); // free slot 3
177	        PipeBarrier<PIPE_ALL>();
178	
179	        // int16 → int8 scalar conversion, write to outQueue
180	        LocalTensor<int8_t> outputInt8 = outQueue_.AllocTensor<int8_t>();
181	        for (int64_t i = 0; i < tileK; i++) {
182	            outputInt8.SetValue(i, static_cast<int8_t>(tempInt16.GetValue(i)));
183	        }
184	        inQueue_.FreeTensor(tempInt16); // free int16 slot
185	        PipeBarrier<PIPE_ALL>();
186	
187	        outQueue_.EnQue(outputInt8);
188	        LocalTensor<int8_t> outData = outQueue_.DeQue<int8_t>();
189	
190	        int64_t outGmOffset = n * innerSize_ * channelSize_ + idx * channelSize_ + kStart;
191	        DataCopyExtParams op;
192	        op.blockCount = 1;
193	        op.blockLen = static_cast<uint32_t>(tileK * sizeof(int8_t));
194	        op.srcStride = 0; op.dstStride = 0;
195	        DataCopyPad(outputGm_[outGmOffset], outData, op);
196	        PipeBarrier<PIPE_ALL>();
197	        outQueue_.FreeTensor(outData);
198	    }
199	
200	private:
201	    TPipe pipe_;
202	    TQue<TPosition::VECIN, IN_BUF_NUM> inQueue_;
203	    TQue<TPosition::VECOUT, OUT_BUF_NUM> outQueue_;
204	
205	    GlobalTensor<int8_t> inputGm_;
206	    GlobalTensor<int32_t> indicesGm_;
207	    GlobalTensor<float> updatesGm_;
208	    GlobalTensor<float> scalesGm_;
209	    GlobalTensor<float> zpGm_;
210	    GlobalTensor<int8_t> outputGm_;
211	
212	    int64_t batchSize_ = 0;
