{"content": "#include "kernel_operator.h"

using namespace AscendC;

constexpr int64_t BUFFER_NUM = 2;

class KernelEmbeddingInitLayernormBackward {
public:
    __aicore__ inline KernelEmbeddingInitLayernormBackward() {}

    __aicore__ inline void Init(
        GM_ADDR gradOutput, GM_ADDR inputIds, GM_ADDR hiddenStates,
        GM_ADDR rstd, GM_ADDR normWeight,
        GM_ADDR gradEmbedWeight, GM_ADDR gradNormWeight,
        int64_t totalRows, int64_t hiddenSize, int64_t vocabSize,
        int64_t formerNum, int64_t formerRows, int64_t tailNum, int64_t tailRows);

    __aicore__ inline void Process();

private:
    __aicore__ inline void CopyIn(int64_t row);
    __aicore__ inline void Compute(int64_t row);
    __aicore__ inline void CopyOut(int64_t row);
    __aicore__ inline void FinalizeNormWeight();

    TPipe pipe;
    TQue<TPosition::VECIN, BUFFER_NUM> inQueueGrad;
    TBuf<TPosition::VECCALC> gradOutputFp32Buf;
    TBuf<TPosition::VECCALC> hiddenFp32Buf;
    TBuf<TPosition::VECCALC> normWeightFp32Buf;
    TBuf<TPosition::VECCALC> workBuf;
    TBuf<TPosition::VECCALC> partialNormBuf;
    TBuf<TPosition::VECCALC> gradHiddenFp32Buf;
    TBuf<TPosition::VECCALC> gradHiddenBf16Buf;

    GlobalTensor<bfloat16_t> gradOutputGm;
    GlobalTensor<int32_t> inputIdsGm;
    GlobalTensor<float> hiddenStatesGm;
    GlobalTensor<float> rstdGm;
    GlobalTensor<float> normWeightGm;
    GlobalTensor<bfloat16_t> gradEmbedWeightGm;
    GlobalTensor<bfloat16_t> gradNormWeightGm;

    int64_t totalRows_;
    int64_t hiddenSize_;
    int64_t vocabSize_;
    int64_t formerNum_;
    int64_t formerRows_;
    int64_t tailNum_;
    int64_t tailRows_;

    int64_t rowStart_;
    int64_t rowEnd_;
};

// =========================== Init ============================

__aicore__ inline void KernelEmbeddingInitLayernormBackward::Init(
    GM_ADDR gradOutput, GM_ADDR inputIds, GM_ADDR hiddenStates,
    GM_ADDR rstd, GM_ADDR normWeight,
    GM_ADDR gradEmbedWeight, GM_ADDR gradNormWeight,
    int64_t totalRows, int64_t hiddenSize, int64_t vocabSize,
    int64_t formerNum, int64_t formerRows, int64_t tailNum, int64_t tailRows)
{
    totalRows_ = totalRows;
    hiddenSize_ = hiddenSize;
    vocabSize_ = vocabSize;
    formerNum_ = formerNum;
    formerRows_ = formerRows;
    tailNum_ = tailNum;
    tailRows_ = tailRows;

    int64_t blockIdx = GetBlockIdx();
    if (blockIdx < formerNum_) {
        rowStart_ = blockIdx * formerRows_;
        rowEnd_ = rowStart_ + formerRows_;
    } else {
        int64_t tailIdx = blockIdx - formerNum_;
        rowStart_ = formerNum_ * formerRows_ + tailIdx * tailRows_;
        rowEnd_ = rowStart_ + tailRows_;
    }
    if (rowEnd_ > totalRows_) rowEnd_ = totalRows_;

    // Set global buffers (row-major, contiguous)
    int64_t gradRowBytes = hiddenSize_ * sizeof(bfloat16_t);
    int64_t hiddenRowElements = hiddenSize_;
    int64_t rstdRowElements = 1;

    gradOutputGm.SetGlobalBuffer((__gm__ bfloat16_t*)gradOutput, totalRows_ * hiddenSize_);
    inputIdsGm.SetGlobalBuffer((__gm__ int32_t*)inputIds, totalRows_);
    hiddenStatesGm.SetGlobalBuffer((__gm__ float*)hiddenStates, totalRows_ * hiddenSize_);
    rstdGm.SetGlobalBuffer((__gm__ float*)rstd, totalRows_);
    normWeightGm.SetGlobalBuffer((__gm__ float*)normWeight, hiddenSize_);
    gradEmbedWeightGm.SetGlobalBuffer((__gm__ bfloat16_t*)gradEmbedWeight, vocabSize_ * hiddenSize_);
    gradNormWeightGm.SetGlobalBuffer((__gm__ bfloat16_t*)gradNormWeight, hiddenSize_);

    // Allocate UB buffers
    pipe.InitBuffer(inQueueGrad, BUFFER_NUM, gradRowBytes);
    pipe.InitBuffer(gradOutputFp32Buf, hiddenSize_ * sizeof(float));
    pipe.InitBuffer(hiddenFp32Buf, hiddenSize_ * sizeof(float));
    pipe.InitBuffer(normWeightFp32Buf, hiddenSize_ * sizeof(float));
    pipe.InitBuffer(workBuf, hiddenSize_ * sizeof(float));
    pipe.InitBuffer(partialNormBuf, hiddenSize_ * sizeof(float));
    pipe.InitBuffer(gradHiddenFp32Buf, hiddenSize_ * sizeof(float));
    pipe.InitBuffer(gradHiddenBf16Buf, hiddenSize_ * sizeof(bfloat16_t));

    // Load norm_weight (fp32) once, reused for all rows
    {
        LocalTensor<float> nwFp32 = normWeightFp32Buf.Get<float>();
        DataCopyExtParams cp;
        cp.blockCount = 1;
        cp.blockLen = static_cast<uint32_t>(hiddenSize_ * sizeof(float));
        cp.srcStride = 0;
        cp.dstStride = 0;
        DataCopyPadExtParams<float> pp;
        pp.isPad = false;
        DataCopyPad(nwFp32, normWeightGm, cp, pp);
        PipeBarrier<PIPE_ALL>();
    }

    // Initialize partialNormBuf to zero
    {
        LocalTensor<float> pnBuf = partialNormBuf.Get<float>();
        Duplicate(pnBuf, 0.0f, hiddenSize_);
    }
}

// =========================== Process ============================

__aicore__ inline void KernelEmbeddingInitLayernormBackward::Process() {
    int64_t blockIdx = GetBlockIdx();

    // Skip if this core has no rows
    if (rowStart_ >= rowEnd_) return;

    for (int64_t row = rowStart_; row < rowEnd_; ++row) {
        CopyIn(row);
        Compute(row);
        CopyOut(row);
    }

    FinalizeNormWeight();
}

// =========================== CopyIn ============================

__aicore__ inline void KernelEmbeddingInitLayernormBackward::CopyIn(int64_t row) {
    // 1. Load grad_output row (bf16) via TQue double-buffer
    //    Cast to fp32 after DeQue
    {
        LocalTensor<bfloat16_t> gradBf16 = inQueueGrad.AllocTensor<bfloat16_t>();
        DataCopyExtParams cp;
        cp.blockCount = 1;
        cp.blockLen = static_cast<uint32_t>(hiddenSize_ * sizeof(bfloat16_t));
        cp.srcStride = 0;
        cp.dstStride = 0;
        DataCopyPadExtParams<bfloat16_t> pp;
        pp.isPad = false;
        DataCopyPad(gradBf16, gradOutputGm[row * hiddenSize_], cp, pp);
        PipeBarrier<PIPE_ALL>();
        inQueueGrad.EnQue(gradBf16);

        LocalTensor<bfloat16_t> gradBf16In = inQueueGrad.DeQue<bfloat16_t>();
        LocalTensor<float> gradFp32 = gradOutputFp32Buf.Get<float>();
        Cast(gradFp32, gradBf16In, RoundMode::CAST_NONE, hiddenSize_);
        inQueueGrad.FreeTensor(gradBf16In);
    }

    // 2. Load hidden_states row (fp32)
    {
        LocalTensor<float> hiddenFp32 = hiddenFp32Buf.Get<float>();
        DataCopyExtParams cp;
        cp.blockCount = 1;
        cp.blockLen = static_cast<uint32_t>(hiddenSize_ * sizeof(float));
        cp.srcStride = 0;
        cp.dstStride = 0;
        DataCopyPadExtParams<float> pp;
        pp.isPad = false;
        DataCopyPad(hiddenFp32, hiddenStatesGm[row * hiddenSize_], cp, pp);
        PipeBarrier<PIPE_ALL>();
    }

    // rstd scalar and input_ids scalar are loaded directly in Compute
}

// =========================== Compute ============================

__aicore__ inline void KernelEmbeddingInitLayernormBackward::Compute(int64_t row) {
    LocalTensor<float> gradFp32 = gradOutputFp32Buf.Get<float>();
    LocalTensor<float> hiddenFp32 = hiddenFp32Buf.Get<float>();
    LocalTensor<float> nwFp32 = normWeightFp32Buf.Get<float>();
    LocalTensor<float> workLocal = workBuf.Get<float>();
    LocalTensor<float> pnLocal = partialNormBuf.Get<float>();
    LocalTensor<float> ghFp32 = gradHiddenFp32Buf.Get<float>();
    LocalTensor<bfloat16_t> ghBf16 = gradHiddenBf16Buf.Get<bfloat16_t>();

    // Load rstd scalar
    float rstdVal = rstdGm.GetValue(row);

    // Load input_ids scalar
    int32_t tokenId = inputIdsGm.GetValue(row);

    // ---- Step 1: normalized = hidden_states_fp32 * rstd ----
    // workBuf = hiddenFp32 * rstdVal
    Muls(workLocal, hiddenFp32, rstdVal, hiddenSize_);

    // ---- Step 2: temp = grad_output_fp32 * normalized ----
    // workBuf = gradFp32 * workLocal
    Mul(workLocal, gradFp32, workLocal, hiddenSize_);

    // ---- Step 3: partialNormBuf += temp (accumulate) ----
    Add(pnLocal, pnLocal, workLocal, hiddenSize_);

    // ---- Step 4: grad_hidden = grad_output_fp32 * norm_weight_fp32 * rstd ----
    // gradHiddenFp32 = gradFp32 * nwFp32
    Mul(ghFp32, gradFp32, nwFp32, hiddenSize_);
    // gradHiddenFp32 *= rstdVal
    Muls(ghFp32, ghFp32, rstdVal, hiddenSize_);

    // ---- Step 5: Cast grad_hidden to bf16 ----
    Cast(ghBf16, ghFp32, RoundMode::CAST_ROUND, hiddenSize_);
}

// =========================== CopyOut ============================

__aicore__ inline void KernelEmbeddingInitLayernormBackward::CopyOut(int64_t row) {
    int32_t tokenId = inputIdsGm.GetValue(row);
    LocalTensor<bfloat16_t> ghBf16 = gradHiddenBf16Buf.Get<bfloat16_t>();

    // Atomic add to grad_embed_weight[tokenId, :]
    SetAtomicAdd<bfloat16_t>();

    DataCopyExtParams cp;
    cp.blockCount = 1;
    cp.blockLen = static_cast<uint32_t>(hiddenSize_ * sizeof(bfloat16_t));
    cp.srcStride = 0;
    cp.dstStride = 0;

    int64_t gmOffset = static_cast<int64_t>(tokenId) * hiddenSize_;
    DataCopyPad(gradEmbedWeightGm[gmOffset], ghBf16, cp);

    SetAtomicNone();
}

// =========================== FinalizeNormWeight ============================

__aicore__ inline void KernelEmbeddingInitLayernormBackward::FinalizeNormWeight() {
    LocalTensor<float> pnLocal = partialNormBuf.Get<float>();
    LocalTensor<bfloat16_t> ghBf16 = gradHiddenBf16Buf.Get<bfloat16_t>();

    // Cast partialNormBuf (fp32) to bf16 in-place in gradHiddenBf16Buf (reuse)
    Cast(ghBf16, pnLocal, RoundMode::CAST_ROUND, hiddenSize_);

    // Atomic add to grad_norm_weight
    SetAtomicAdd<bfloat16_t>();

    DataCopyExtParams cp;
    cp.blockCount = 1;
    cp.blockLen = static_cast<uint32_t>(hiddenSize_ * sizeof(bfloat16_t));
    cp.srcStride = 0;
    cp.dstStride = 0;

    DataCopyPad(gradNormWeightGm[0], ghBf16, cp);

    SetAtomicNone();
}

// =========================== Kernel Entry ============================

extern "C" __global__ __aicore__ void embedding_init_layernorm_backward(
    GM_ADDR gradOutput, GM_ADDR inputIds, GM_ADDR hiddenStates,
    GM_ADDR rstd, GM_ADDR normWeight,
    GM_ADDR gradEmbedWeight, GM_ADDR gradNormWeight,
    GM_ADDR tilingGm)
{
    // Read tiling data from GM
    int64_t totalRows   = *((__gm__ int64_t*)(tilingGm));
    int64_t hiddenSize  = *((__gm__ int64_t*)(tilingGm + 8));
    int64_t vocabSize   = *((__gm__ int64_t*)(tilingGm + 16));
    int64_t formerNum   = *((__gm__ int64_t*)(tilingGm + 24));
    int64_t formerRows  = *((__gm__ int64_t*)(tilingGm + 32));
    int64_t tailNum     = *((__gm__ int64_t*)(tilingGm + 40));
    int64_t tailRows    = *((__gm__ int64_t*)(tilingGm + 48));

    KernelEmbeddingInitLayernormBackward op;
    op.Init(gradOutput, inputIds, hiddenStates, rstd, normWeight,
            gradEmbedWeight, gradNormWeight,
            totalRows, hiddenSize, vocabSize,
            formerNum, formerRows, tailNum, tailRows);
    op.Process();
}
