#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_embedding_init_layernorm_backward.h"

namespace ascend_kernel {

std::tuple<at::Tensor, at::Tensor> embedding_init_layernorm_backward(
    const at::Tensor &grad_output,
    const at::Tensor &input_ids,
    const at::Tensor &hidden_states_fp32,
    const at::Tensor &rstd,
    const at::Tensor &norm_weight)
{
    // ---- Input validation ----
    TORCH_CHECK(grad_output.device().type() == at::DeviceType::PrivateUse1,
                "embedding_init_layernorm_backward: grad_output must be on NPU device");
    TORCH_CHECK(input_ids.device().type() == at::DeviceType::PrivateUse1,
                "embedding_init_layernorm_backward: input_ids must be on NPU device");
    TORCH_CHECK(hidden_states_fp32.device().type() == at::DeviceType::PrivateUse1,
                "embedding_init_layernorm_backward: hidden_states_fp32 must be on NPU device");
    TORCH_CHECK(rstd.device().type() == at::DeviceType::PrivateUse1,
                "embedding_init_layernorm_backward: rstd must be on NPU device");
    TORCH_CHECK(norm_weight.device().type() == at::DeviceType::PrivateUse1,
                "embedding_init_layernorm_backward: norm_weight must be on NPU device");

    TORCH_CHECK(grad_output.scalar_type() == at::kBFloat16,
                "embedding_init_layernorm_backward: grad_output must be bfloat16");
    TORCH_CHECK(hidden_states_fp32.scalar_type() == at::kFloat,
                "embedding_init_layernorm_backward: hidden_states_fp32 must be float32");
    TORCH_CHECK(rstd.scalar_type() == at::kFloat,
                "embedding_init_layernorm_backward: rstd must be float32");
    TORCH_CHECK(norm_weight.scalar_type() == at::kFloat ||
                norm_weight.scalar_type() == at::kBFloat16,
                "embedding_init_layernorm_backward: norm_weight must be float32 or bfloat16");

    TORCH_CHECK(grad_output.dim() == 3,
                "embedding_init_layernorm_backward: grad_output must be 3D (B,S,H)");
    TORCH_CHECK(input_ids.dim() == 2,
                "embedding_init_layernorm_backward: input_ids must be 2D (B,S)");

    // ---- Extract dimensions ----
    int64_t batchSize = grad_output.size(0);
    int64_t seqLen = grad_output.size(1);
    int64_t hiddenSize = grad_output.size(2);
    int64_t totalRows = batchSize * seqLen;

    TORCH_CHECK(hiddenSize == 4096,
                "embedding_init_layernorm_backward: hiddenSize must be 4096, got ", hiddenSize);

    int64_t vocabSize = 65536;  // Fixed vocab size from model

    // ---- Contiguity ----
    at::Tensor gradOutputContig = grad_output.contiguous();
    at::Tensor hiddenStatesContig = hidden_states_fp32.contiguous();
    at::Tensor rstdContig = rstd.contiguous();
    at::Tensor inputIdsContig = input_ids.contiguous();

    // Convert input_ids to int32 (kernel uses int32 indexing)
    auto inputIdsInt32 = inputIdsContig.to(at::kInt).contiguous();

    // Handle norm_weight dtype: always pass fp32 to kernel
    at::Tensor normWeightFp32 = norm_weight.contiguous();
    if (normWeightFp32.scalar_type() != at::kFloat) {
        normWeightFp32 = normWeightFp32.to(at::kFloat).contiguous();
    }

    // ---- Create output tensors ----
    auto gradEmbedWeight = at::zeros({vocabSize, hiddenSize},
        at::TensorOptions().dtype(at::kBFloat16).device(at::DeviceType::PrivateUse1));
    auto gradNormWeight = at::zeros({hiddenSize},
        at::TensorOptions().dtype(at::kBFloat16).device(at::DeviceType::PrivateUse1));

    if (totalRows == 0) {
        return std::make_tuple(gradEmbedWeight, gradNormWeight);
    }

    // ---- Get platform info ----
    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());

    // ---- Block-level Tiling: split rows across cores ----
    int64_t usedCoreNum = (totalRows < coreNum) ? totalRows : coreNum;
    if (usedCoreNum < 1) usedCoreNum = 1;

    int64_t formerRows = (totalRows + usedCoreNum - 1) / usedCoreNum;
    int64_t formerNum = totalRows % usedCoreNum;
    if (formerNum == 0) formerNum = usedCoreNum;
    int64_t tailNum = usedCoreNum - formerNum;
    int64_t tailRows = totalRows / usedCoreNum;

    // ---- Prepare tiling data (passed via GM) ----
    struct TilingData {
        int64_t totalRows;
        int64_t hiddenSize;
        int64_t vocabSize;
        int64_t formerNum;
        int64_t formerRows;
        int64_t tailNum;
        int64_t tailRows;
    };

    TilingData tilingData = {
        totalRows, hiddenSize, vocabSize,
        formerNum, formerRows, tailNum, tailRows
    };

    auto tilingTensorCpu = at::empty({static_cast<int64_t>(sizeof(TilingData))},
                                     at::TensorOptions().dtype(at::kByte));
    std::memcpy(tilingTensorCpu.data_ptr<uint8_t>(), &tilingData, sizeof(TilingData));
    auto tilingTensor = tilingTensorCpu.to(at::DeviceType::PrivateUse1).contiguous();

    // ---- Launch kernel (all params must be lvalues) ----
    int64_t blockDimVal = usedCoreNum;

    EXEC_KERNEL_CMD(embedding_init_layernorm_backward, blockDimVal,
                    gradOutputContig, inputIdsInt32, hiddenStatesContig,
                    rstdContig, normWeightFp32,
                    gradEmbedWeight, gradNormWeight,
                    tilingTensor);

    return std::make_tuple(gradEmbedWeight, gradNormWeight);
}

}  // namespace ascend_kernel
