using namespace AscendC;

constexpr int64_t BUFFER_NUM = 2;

class KernelEmbeddingInitLayernormBackward {
public:
    __aicore__ inline KernelEmbeddingInitLayernormBackward() {}

    __aicore__ inline void Init(
