    TQue<TPosition::VECIN, BUFFER_NUM> inQueueGrad;
    TQue<TPosition::VECOUT, 1> outQueueAtomic;
    TBuf<TPosition::VECCALC> gradOutputFp32Buf;
    TBuf<TPosition::VECCALC> hiddenFp32Buf;
    TBuf<TPosition::VECCALC> normWeightFp32Buf;
