    // Copy bf16 data through VECOUT TQue for proper synchronization
    LocalTensor<bfloat16_t> outLocal = outQueueAtomic.AllocTensor<bfloat16_t>();
    // Copy tmpBf16 → outLocal (UB to UB within TQue slot)
