44	    int64_t hiddenSize = grad_output.size(2);
45	    int64_t totalRows = batchSize * seqLen;
46	
47	    TORCH_CHECK(hiddenSize == 4096,
48	                "embedding_init_layernorm_backward: hiddenSize must be 4096, got ", hiddenSize);
49	
