// =========================== Init ============================

__aicore__ inline void KernelEmbeddingInitLayernormBackward::Init(
    GM_ADDR gradOutput, GM_ADDR inputIds, GM_ADDR hiddenStates,
    GM_ADDR rstd, GM_ADDR normWeight,
    GM_ADDR gradEmbedWeight, GM_ADDR gradNormWeight,
    int64_t totalRows, int64_t hiddenSize, int64_t vocabSize,
    int64_t formerNum, int64_t formerRows, int64_t tailNum, int64_t tailRows)
{
    totalRows_ = totalRows;
    hiddenSize_ = hiddenSize;
    vocabSize_ = vocabSize;
    formerNum_ = formerNum;
    formerRows_ = formerRows;
    tailNum_ = tailNum;
    tailRows_ = tailRows;

    int64_t blockIdx = GetBlockIdx();
    if (blockIdx < formerNum_) {
        rowStart_ = blockIdx * formerRows_;
        rowEnd_ = rowStart_ + formerRows_;
    } else {
        int64_t tailIdx = blockIdx - formerNum_;
        rowStart_ = formerNum_ * formerRows_ + tailIdx * tailRows_;
        rowEnd_ = rowStart_ + tailRows_;
    }
    if (rowEnd_ > totalRows_) rowEnd_ = totalRows_;

    int64_t gradRowBytes = hiddenSize_ * sizeof(bfloat16_t);

    // Set global buffers — outputs are fp32 for precise atomic accumulation
    gradOutputGm.SetGlobalBuffer((__gm__ bfloat16_t*)gradOutput, totalRows_ * hiddenSize_);
    inputIdsGm.SetGlobalBuffer((__gm__ int32_t*)inputIds, totalRows_);
    hiddenStatesGm.SetGlobalBuffer((__gm__ float*)hiddenStates, totalRows_ * hiddenSize_);
    rstdGm.SetGlobalBuffer((__gm__ float*)rstd, totalRows_);
    normWeightGm.SetGlobalBuffer((__gm__ float*)normWeight, hiddenSize_);
    gradEmbedWeightGm.SetGlobalBuffer((__gm__ float*)gradEmbedWeight, vocabSize_ * hiddenSize_);
    gradNormWeightGm.SetGlobalBuffer((__gm__ float*)gradNormWeight, hiddenSize_);

    // Allocate UB buffers
    pipe.InitBuffer(inQueueGrad, BUFFER_NUM, gradRowBytes);
    pipe.InitBuffer(gradOutputFp32Buf, hiddenSize_ * sizeof(float));
    pipe.InitBuffer(hiddenFp32Buf, hiddenSize_ * sizeof(float));
    pipe.InitBuffer(normWeightFp32Buf, hiddenSize_ * sizeof(float));
    pipe.InitBuffer(workBuf, hiddenSize_ * sizeof(float));
    pipe.InitBuffer(partialNormBuf, hiddenSize_ * sizeof(float));
    pipe.InitBuffer(gradHiddenFp32Buf, hiddenSize_ * sizeof(float));

    // Load norm_weight (fp32) once, reused for all rows
    {
        LocalTensor<float> nwFp32 = normWeightFp32Buf.Get<float>();
        DataCopyExtParams cp;
        cp.blockCount = 1;
        cp.blockLen = static_cast<uint32_t>(hiddenSize_ * sizeof(float));
        cp.srcStride = 0;
        cp.dstStride = 0;
        DataCopyPadExtParams<float> pp;
        pp.isPad = false;
        DataCopyPad(nwFp32, normWeightGm, cp, pp);
        PipeBarrier<PIPE_ALL>();
    }

    // Initialize partialNormBuf to zero
    {
        LocalTensor<float> pnBuf = partialNormBuf.Get<float>();
        Duplicate(pnBuf, 0.0f, hiddenSize_);
