// =========================== Process ============================

__aicore__ inline void KernelEmbeddingInitLayernormBackward::Process() {
    if (rowStart_ >= rowEnd_) return;

    for (int64_t row = rowStart_; row < rowEnd_; ++row) {
        CopyIn(row);
        Compute(row);
        CopyOut(row);
    }

    FinalizeNormWeight();
}

// =========================== CopyIn ============================

__aicore__ inline void KernelEmbeddingInitLayernormBackward::CopyIn(int64_t row) {
    // Load grad_output row (bf16) via TQue, Cast to fp32
    {
        LocalTensor<bfloat16_t> gradBf16 = inQueueGrad.AllocTensor<bfloat16_t>();
        DataCopyExtParams cp;
        cp.blockCount = 1;
        cp.blockLen = static_cast<uint32_t>(hiddenSize_ * sizeof(bfloat16_t));
        cp.srcStride = 0;
        cp.dstStride = 0;
        DataCopyPadExtParams<bfloat16_t> pp;
        pp.isPad = false;
        DataCopyPad(gradBf16, gradOutputGm[row * hiddenSize_], cp, pp);
        inQueueGrad.EnQue(gradBf16);

        LocalTensor<bfloat16_t> gradBf16In = inQueueGrad.DeQue<bfloat16_t>();
        LocalTensor<float> gradFp32 = gradOutputFp32Buf.Get<float>();
        Cast(gradFp32, gradBf16In, RoundMode::CAST_NONE, hiddenSize_);
        inQueueGrad.FreeTensor(gradBf16In);
    }

    // Load hidden_states row (fp32)
    {
        LocalTensor<float> hiddenFp32 = hiddenFp32Buf.Get<float>();
        DataCopyExtParams cp;
        cp.blockCount = 1;
        cp.blockLen = static_cast<uint32_t>(hiddenSize_ * sizeof(float));
        cp.srcStride = 0;
        cp.dstStride = 0;
        DataCopyPadExtParams<float> pp;
        pp.isPad = false;
        DataCopyPad(hiddenFp32, hiddenStatesGm[row * hiddenSize_], cp, pp);
        PipeBarrier<PIPE_ALL>();
    }
}

// =========================== Compute ============================

__aicore__ inline void KernelEmbeddingInitLayernormBackward::Compute(int64_t row) {
    LocalTensor<float> gradFp32 = gradOutputFp32Buf.Get<float>();
    LocalTensor<float> hiddenFp32 = hiddenFp32Buf.Get<float>();
    LocalTensor<float> nwFp32 = normWeightFp32Buf.Get<float>();
    LocalTensor<float> workLocal = workBuf.Get<float>();
    LocalTensor<float> pnLocal = partialNormBuf.Get<float>();
    LocalTensor<float> ghFp32 = gradHiddenFp32Buf.Get<float>();

    float rstdVal = rstdGm.GetValue(row);

    // Step 1: normalized = hidden_states_fp32 * rstd
    Muls(workLocal, hiddenFp32, rstdVal, hiddenSize_);

    // Step 2: temp = grad_output_fp32 * normalized
    Mul(workLocal, gradFp32, workLocal, hiddenSize_);

    // Step 3: partialNormBuf += temp (accumulate)
    Add(pnLocal, pnLocal, workLocal, hiddenSize_);

    // Step 4: grad_hidden = grad_output_fp32 * norm_weight_fp32 * rstd
    Mul(ghFp32, gradFp32, nwFp32, hiddenSize_);
    Muls(ghFp32, ghFp32, rstdVal, hiddenSize_);

    // ghFp32 stays in fp32 — no bf16 cast needed
}

// =========================== CopyOut ============================

__aicore__ inline void KernelEmbeddingInitLayernormBackward::CopyOut(int64_t row) {
    int32_t tokenId = inputIdsGm.GetValue(row);
    LocalTensor<float> ghFp32 = gradHiddenFp32Buf.Get<float>();

    // Ensure all vector computation is complete before DMA reads
    PipeBarrier<PIPE_ALL>();

    int64_t gmOffset = static_cast<int64_t>(tokenId) * hiddenSize_;

    // fp32 atomic add for precise accumulation
    SetAtomicAdd<float>();

    DataCopyExtParams cp;
    cp.blockCount = 1;
    cp.blockLen = static_cast<uint32_t>(hiddenSize_ * sizeof(float));
    cp.srcStride = 0;
    cp.dstStride = 0;

    DataCopyPad(gradEmbedWeightGm[gmOffset], ghFp32, cp);

    SetAtomicNone();
}

// =========================== FinalizeNormWeight ============================

__aicore__ inline void KernelEmbeddingInitLayernormBackward::FinalizeNormWeight() {
    LocalTensor<float> pnLocal = partialNormBuf.Get<float>();

    // Ensure all computation is complete
    PipeBarrier<PIPE_ALL>();

    // fp32 atomic add to grad_norm_weight
    SetAtomicAdd<float>();

    DataCopyExtParams cp;
    cp.blockCount = 1;
    cp.blockLen = static_cast<uint32_t>(hiddenSize_ * sizeof(float));
    cp.srcStride = 0;
    cp.dstStride = 0;

    DataCopyPad(gradNormWeightGm[0], pnLocal, cp);

    SetAtomicNone();
}

